create table if not exists public.email_log (id uuid primary key default gen_random_uuid(), to_email citext not null, template text not null, status text not null check (status in ('sent','failed')), provider_message_id text, error text, created_at timestamptz not null default now()); alter table public.email_log enable row level security; revoke all on table public.email_log from anon, authenticated;
